import 'package:flutter/material.dart';
import 'package:intl/intl.dart';
import '../models/medical_models.dart';
import '../services/database_service.dart';
import '../services/notification_service.dart';

class AddVisitScreen extends StatefulWidget { const AddVisitScreen({super.key}); @override State<AddVisitScreen> createState()=>_AddVisitScreenState(); }
class _AddVisitScreenState extends State<AddVisitScreen>{final clinic=TextEditingController(),reason=TextEditingController(),diagnosis=TextEditingController(),doctor=TextEditingController(),prescription=TextEditingController();DateTime date=DateTime.now();TimeOfDay time=const TimeOfDay(hour:10,minute:0);
  Future<void>save()async{if(clinic.text.trim().isEmpty)return;final id=await DatabaseService.instance.addVisit(ClinicVisit(clinic:clinic.text.trim(),date:DateFormat('yyyy-MM-dd').format(date),time:'${time.hour.toString().padLeft(2,'0')}:${time.minute.toString().padLeft(2,'0')}',reason:reason.text.trim(),diagnosis:diagnosis.text.trim(),doctor:doctor.text.trim(),prescription:prescription.text.trim()));final appointment=DateTime(date.year,date.month,date.day,time.hour,time.minute);await NotificationService.scheduleAppointment(visitId:id,clinic:clinic.text.trim(),appointment:appointment);if(mounted)Navigator.pop(context,true);}
  @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Clinic Appointment')),body:ListView(padding:const EdgeInsets.all(18),children:[_f(clinic,'Clinic / Hospital name',Icons.local_hospital),_f(doctor,'Doctor (optional)',Icons.person),_f(reason,'Reason for visit',Icons.help_outline),_f(diagnosis,'Diagnosis (optional)',Icons.healing),_f(prescription,'Prescription / notes',Icons.receipt_long,max:4),ListTile(contentPadding:EdgeInsets.zero,leading:const Icon(Icons.calendar_today),title:const Text('Appointment date'),subtitle:Text(DateFormat('dd MMM yyyy').format(date)),onTap:()async{final d=await showDatePicker(context:context,firstDate:DateTime.now(),lastDate:DateTime(2100),initialDate:date);if(d!=null)setState(()=>date=d);}),ListTile(contentPadding:EdgeInsets.zero,leading:const Icon(Icons.access_time),title:const Text('Appointment time'),subtitle:Text(time.format(context)),onTap:()async{final t=await showTimePicker(context:context,initialTime:time);if(t!=null)setState(()=>time=t);}),const SizedBox(height:10),Card(child:const Padding(padding:EdgeInsets.all(12),child:Text('Notifications are scheduled for exactly 24 hours before the appointment and at the appointment time.'))),const SizedBox(height:10),FilledButton.icon(onPressed:save,icon:const Icon(Icons.notifications_active),label:const Text('Save Appointment & Reminders'))]));
  Widget _f(TextEditingController c,String l,IconData i,{int max=1})=>Padding(padding:const EdgeInsets.only(bottom:12),child:TextField(controller:c,maxLines:max,decoration:InputDecoration(labelText:l,prefixIcon:Icon(i))));
}
